import {HEROES,heroById} from './heroes.js';
import {heroImage} from './art/heroes.js';
import {GARDEN_ORDER,GARDENS} from './gardens.js';
export function heroCards(meta){return '<div class="hero-cards">'+HEROES.map(h=>{const unlocked=meta.heroesUnlocked.includes(h.id),best=meta.highestCompletedWave||0;return '<article class="hero-card '+(unlocked?'':'locked')+'"><img src="'+heroImage(h.id)+'" alt=""><h3>'+h.name+'</h3><b>'+h.role+' · '+(unlocked?'UNLOCKED':'LOCKED')+'</b><p>'+h.description+'</p><p>Completar Wave '+h.unlockWave+' · Best: '+best+' / '+h.unlockWave+'</p><progress max="'+h.unlockWave+'" value="'+Math.min(best,h.unlockWave)+'"></progress><p>HP '+h.hp+' · Dano '+h.attackDamage+' / '+h.attackInterval+'s · Range '+h.attackRange+'</p><p><b>PASSIVE</b> '+h.passive+'</p><p><b>ABILITY</b> '+h.ability+' · '+h.abilityCooldown+'s</p><small>Target: '+h.targetStrategy+' · Aggro '+h.aggroRange+' · Leash '+h.leashRange+'</small></article>'}).join('')+'</div>'}
export function nextHero(meta){const h=HEROES.find(h=>!meta.heroesUnlocked.includes(h.id));return h?'<p><b>NEXT HERO · '+h.name+'</b><br>Completar Wave '+h.unlockWave+' · Best: '+(meta.highestCompletedWave||0)+' / '+h.unlockWave+'</p>':'<p>Todos os Heroes desbloqueados.</p>'}
export function heroSummary(game){return '<h3>HEROES</h3>'+Object.values(game.heroRoster).map(h=>'<p><b>'+heroById(h.id).name+'</b> · '+(GARDENS[h.gardenId||h.lastGardenId]?.name||'Reserva')+(h.rescued?' · RESCUED':'')+'<br>'+h.metrics.kills+' kills · '+Math.round(h.metrics.damage)+' damage · '+Math.round(h.metrics.healing)+' healing · '+h.metrics.downs+' downs</p>').join('')}
export function setupHeroUI({game:g,meta,show,close,toast,persist}){
 const $=id=>document.getElementById(id);
 function deployment(done=close){if(g.state!=='intermission')return;g.paused=true;show('<h2 id="dialog-title">HERO DEPLOYMENT</h2><p>1 Hero por Garden. Trocas disponíveis apenas durante preparação.</p><div class="hero-deployment">'+GARDEN_ORDER.map(id=>{const garden=g.gardens[id],current=g.heroForGarden(id);return '<label><b>'+GARDENS[id].name+'</b><select data-hero-garden="'+id+'" '+(!garden||garden.lost?'disabled':'')+'><option value="">'+(!garden?'Locked':garden.lost?'Lost':'No Hero')+'</option>'+HEROES.filter(h=>meta().heroesUnlocked.includes(h.id)).map(h=>{const assigned=g.gardenForHero(h.id);return '<option value="'+h.id+'" '+(current?.id===h.id?'selected':'')+' '+(assigned&&assigned.id!==id?'disabled':'')+'>'+h.name+(assigned&&assigned.id!==id?' · ASSIGNED '+assigned.name:'')+'</option>'}).join('')+'</select></label>'}).join('')+'</div><button id="hero-ready" class="primary">PRONTO · PREPARAR DEFESA</button>','heroDeployment');document.querySelectorAll('[data-hero-garden]').forEach(select=>select.onchange=()=>{const gardenId=select.dataset.heroGarden,previous=g.heroForGarden(gardenId);if(previous)g.unassignHero(previous.id);if(select.value)g.assignHero(select.value,gardenId);deployment(done)});$('hero-ready').onclick=done}
 const button=document.createElement('button');button.id='heroes';button.textContent='HEROES';document.querySelector('.wave-control').append(button);button.onclick=()=>deployment();const hud=document.createElement('section');hud.id='hero-hud';hud.className='panel hero-hud';document.querySelector('aside').prepend(hud);
 g.events.on('hero:downed',({hero,garden})=>{if(garden.id!==g.activeGardenId)toast(heroById(hero.id).name+' DOWN · '+garden.name)});g.events.on('hero:rescued',({hero,garden})=>toast(heroById(hero.id).name+' RESCUED · '+garden.name));g.events.on('hero:unlocked',persist);
 function update(){button.disabled=g.state!=='intermission';const h=g.heroForGarden(g.activeGardenId);hud.hidden=!h;if(!h)return;const d=heroById(h.id);hud.title=d.role+'\n'+d.passive+'\n'+d.ability;hud.innerHTML='<b>'+d.name+'</b><small>'+d.role+' · '+(h.downed?'DOWNED':h.state)+'</small><label>HP '+Math.ceil(h.hp)+' / '+Math.ceil(h.maxHp)+'<progress value="'+h.hp+'" max="'+h.maxHp+'"></progress></label><label>'+d.ability+'<progress value="'+(d.abilityCooldown-h.abilityTimer)+'" max="'+d.abilityCooldown+'"></progress></label>'+(location.search.includes('debug=1')?'<small>Target '+(h.targetUid??'none')+' · Aggro '+d.aggroRange+'</small>':'')}
 function unlock(choices){const h=choices[0];show('<div class="hero-unlock"><small>NEW HERO UNLOCKED</small><h2 id="dialog-title">'+h.name+'</h2><img src="'+heroImage(h.id)+'" alt=""><h3>'+h.role+'</h3><p>'+h.description+'</p><p>Disponível permanentemente e nesta run durante a preparação.</p><button class="primary" id="hero-continue">CONTINUAR</button></div>','heroUnlock');$('hero-continue').onclick=()=>{g.continueHeroUnlock();if(g.state==='intermission')deployment()}}
 return {deployment,update,unlock};
}
